+    public async Task AllowPrivateRequiredIsReported()
+    {
+        string input = Preamble + @"
+[{|MsgPack015:MessagePackObject(SuppressSourceGeneration = true)|}]
+public class Foo
+{
+    [Key(0)]
+    private string member;
+}
+";
+
+        await new VerifyCS.Test
