+    public async Task DuplicateStringKeysAreReportedWithoutAnalyzerFailure()
+    {
+        string input = Preamble + @"
+[MessagePackObject(SuppressSourceGeneration = true)]
+public class Foo
+{
+    [Key(""a"")]
